-- composition of rule kernels L:extract_equijoin_predicate x L:type_coercion (datafusion), template union
SELECT count(*) FROM (SELECT 1 AS k FROM (SELECT 10::bigint AS c0, FALSE AS c1, make_array('a', 'b') AS c2, make_array(NULL, 1) AS c3) AS ka UNION ALL SELECT 2 AS k FROM (SELECT '2000-01-01'::date AS c0 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c0 = a2.c0)) GROUP BY a1.c0, a2.c0 UNION ALL (SELECT '2024-02-29'::date AS c0 UNION SELECT '1999-12-31'::date AS c0)) AS kb) AS u;
